:root {
  --ink: #000000;
  --paper: #FFFFFF;
  --accent: #B54131;
  --border: #D6D6D6;
  --support: #555555;
  --radius: 5px;
  --space: 16px;
}

body { margin: 0; padding: 24px; background: var(--paper); color: var(--ink); font-family: "Noto Sans", sans-serif; }
.catalog { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
.card { padding: var(--space); border: 1px solid var(--border); border-radius: var(--radius); background: var(--paper); }
.card h2 { margin: 0 0 8px; font-size: 20px; }
.cta { padding: 8px 12px; border: 0; border-radius: var(--radius); background: var(--accent); color: var(--paper); font: inherit; }
@media (max-width: 640px) {
  .catalog { grid-template-columns: 1fr; }
}
